import{_ as l,C as o,o as c,c as u,a6 as t,E as a,j as s,a as n}from"./chunks/framework.5dd0l9Wo.js";const v=JSON.parse('{"title":"Business Logic Vulnerabilities","description":"Client-side trust, price and quantity manipulation, coupon abuse, workflow skips, and email parsing discrepancies.","frontmatter":{"title":"Business Logic Vulnerabilities","description":"Client-side trust, price and quantity manipulation, coupon abuse, workflow skips, and email parsing discrepancies."},"headers":[],"relativePath":"business-logic/index.md","filePath":"business-logic/index.md"}'),d={name:"business-logic/index.md"};function p(h,e,b,g,f,m){const i=o("LabGroup"),r=o("TopicComplete");return c(),u("div",null,[e[0]||(e[0]=t(`<h1 id="business-logic-vulnerabilities" tabindex="-1">Business Logic Vulnerabilities <a class="header-anchor" href="#business-logic-vulnerabilities" aria-label="Permalink to &quot;Business Logic Vulnerabilities&quot;">​</a></h1><p class="wd-section-lede">Every component can be working exactly as designed and the system can still be exploitable. Logic bugs live in the assumptions between components: that the client sends a price, that a quantity is positive, that step 2 always follows step 1.</p><div class="wd-callout"><p><strong>The model.</strong> A business rule is a constraint over state, not a validation of a single field. &quot;A discount applies once per user&quot; is a rule about history. &quot;The price is £10&quot; is a rule about authority. If either is enforced by the client, or by a check that does not survive concurrency, the rule is advisory.</p></div><h2 id="trust-boundaries-in-a-workflow" tabindex="-1">Trust boundaries in a workflow <a class="header-anchor" href="#trust-boundaries-in-a-workflow" aria-label="Permalink to &quot;Trust boundaries in a workflow&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>browser                          server</span></span>
<span class="line"><span>  │  price=100, qty=1  ────────▶  charge(price*qty)</span></span>
<span class="line"><span>  │  coupon=NEWCUSTOMER ───────▶  discount = coupon.valid ? 20% : 0</span></span>
<span class="line"><span>  │  step=3 ───────────────────▶  ship(order)   ← was step 1 authorised?</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>Each arrow is a place where the client asserts something. The question is which assertions the server re-derives.</p><h2 id="client-side-controls-are-not-controls" tabindex="-1">Client-side controls are not controls <a class="header-anchor" href="#client-side-controls-are-not-controls" aria-label="Permalink to &quot;Client-side controls are not controls&quot;">​</a></h2><p>Prices, quantities, discount flags, and role fields sent by the browser are requests, not facts. The server must look up the authoritative value.</p>`,8)),a(i,{ids:"business-logic-lab-logic-flaws-excessive-trust-in-client-side-controls, business-logic-lab-logic-flaws-high-level, business-logic-lab-logic-flaws-low-level"}),e[1]||(e[1]=t('<details class="details custom-block"><summary>🔬 Under the Hood: why integer overflow still matters</summary><p>A signed 32-bit integer wraps at 2,147,483,647. If the server accepts a quantity and multiplies it by a unit price without bounds, a large enough quantity can produce a negative total (or a small positive one) after wraparound. The application then treats a negative total as store credit or as a valid payment.</p><p>The same class appears with floating-point rounding, currency conversion, and &quot;buy 10, get 1 free&quot; arithmetic. Validate ranges and use decimal types for money; never rely on the language&#39;s default integer semantics across a boundary.</p></details><h2 id="coupons-refunds-and-rule-interaction" tabindex="-1">Coupons, refunds, and rule interaction <a class="header-anchor" href="#coupons-refunds-and-rule-interaction" aria-label="Permalink to &quot;Coupons, refunds, and rule interaction&quot;">​</a></h2><p>Rules interact in ways the developer did not enumerate:</p><ul><li>a coupon can be applied repeatedly if the &quot;used&quot; flag is set after the response;</li><li>two coupons can stack when the UI only allows one;</li><li>a refund credits the full price even after a discount;</li><li>a gift-card balance can be transferred to itself.</li></ul>',4)),a(i,{ids:"business-logic-lab-logic-flaws-flawed-enforcement-of-business-rules, business-logic-lab-logic-flaws-inconsistent-security-controls, business-logic-lab-logic-flaws-infinite-money"}),e[2]||(e[2]=s("h2",{id:"workflow-and-state-machines",tabindex:"-1"},[n("Workflow and state machines "),s("a",{class:"header-anchor",href:"#workflow-and-state-machines","aria-label":'Permalink to "Workflow and state machines"'},"​")],-1)),e[3]||(e[3]=s("p",null,"The server must verify that the current state permits the requested transition. Checking the user's role on the first step is not enough if the final step accepts a direct request.",-1)),a(i,{ids:"business-logic-lab-logic-flaws-weak-isolation-on-dual-use-endpoint, business-logic-lab-logic-flaws-insufficient-workflow-validation, business-logic-lab-logic-flaws-authentication-bypass-via-flawed-state-machine"}),e[4]||(e[4]=s("h2",{id:"input-that-means-two-things",tabindex:"-1"},[n("Input that means two things "),s("a",{class:"header-anchor",href:"#input-that-means-two-things","aria-label":'Permalink to "Input that means two things"'},"​")],-1)),e[5]||(e[5]=s("p",null,"Parsers disagree. An email address can be valid to the registration parser and invalid to the access-control parser; a Unicode domain can normalise differently; a numeric string can be read as octal, decimal, or a float.",-1)),a(i,{ids:"business-logic-lab-logic-flaws-inconsistent-handling-of-exceptional-input, business-logic-lab-logic-flaws-bypassing-access-controls-using-email-address-parsing-discrepancies"}),e[6]||(e[6]=s("h2",{id:"cryptographic-oracles-in-business-flows",tabindex:"-1"},[n("Cryptographic oracles in business flows "),s("a",{class:"header-anchor",href:"#cryptographic-oracles-in-business-flows","aria-label":'Permalink to "Cryptographic oracles in business flows"'},"​")],-1)),e[7]||(e[7]=s("p",null,'An "encryption oracle" endpoint that encrypts and decrypts user data with a fixed key can be used to forge a privileged token. The bug is not the cipher; it is exposing both directions of the primitive and using the result as an authorisation decision.',-1)),a(i,{ids:"business-logic-lab-logic-flaws-authentication-bypass-via-encryption-oracle"}),e[8]||(e[8]=t('<details class="details custom-block"><summary>⚙️ Engine Variations: how frameworks parse form and JSON bodies</summary><ul><li><strong>PHP</strong> parses duplicate keys by last-one-wins; <code>a[]=1&amp;a[]=2</code> produces an array; <code>a[b]=c</code> produces a nested map.</li><li><strong>Express</strong> with <code>qs</code> creates nested objects and arrays from bracket syntax.</li><li><strong>Spring</strong> binds request parameters to object fields, which is how mass assignment happens.</li><li><strong>Rails</strong> strong parameters are a defence only if every controller uses them.</li></ul><p>Duplicate parameters are a classic logic bypass: the WAF validates the first <code>price</code>, the framework uses the last.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Re-derive every authoritative value server-side. Model workflows as explicit state machines with a transition guard per step. Enforce invariants in the database (unique constraints, non-negative quantities, single-use coupons). Test with concurrent requests and with duplicate parameters. Log rejected transitions.</p></div>',2)),a(r,{"topic-id":"business-logic-vulnerabilities",label:"Mark business logic complete"})])}const y=l(d,[["render",p]]);export{v as __pageData,y as default};
